function resolveWorkflowArtifactDisk(workflow, drive) {
    const name = workflow.artifactDisk ?? drive.default;
    const disk = drive.disks[name];
    if (!disk) {
        throw new Error(`Workflow Artifact disk "${name}" is not configured`);
    }
    if (disk.driver !== 'fs') {
        throw new Error(`Workflow Artifact disk "${name}" must use the fs/local driver`);
    }
    if (disk.visibility !== 'private') {
        throw new Error(`Workflow Artifact disk "${name}" must have private visibility`);
    }
    return disk;

